1	import {WebSocket} from 'ws';
2	import type {SessionEntry} from '../../types/session.js';
3	import type {ChatSession} from '../../types/session.js';
4	import {ErrorCodes} from '../../types/messages.js';
5	import type {ListSessionsMessage, OutgoingMessage, SessionSummaryFrame} from '../../types/messages.js';
6	import type {SessionStore, SessionSummary} from '../../types/sessionStore.js';
7	import {ThinkingTagParser, ParsedSegment} from '../../infrastructure/parsers/thinkingTagParser.js';
8	import {validateMessage} from './validation.js';
9	import type {ValidationResult} from './validation.js';
10	import {PerSessionLock} from '../../shared/perSessionLock.js';
11	import type {ChatOrchestrator} from '../../orchestration/chatOrchestrator.js';
12	import {AIError} from '../../types/ai.js';
13	import type {MessageChunk} from '../../types/ai.js';
14	import {
15	  createUserEntry,
16	  createAssistantEntry,
17	  createThinkingEntry,
18	  createToolEntry,
19	} from '../../orchestration/entryFactories.js';
20	import {appendEntry, appendDelta, commitEntry, markTruncated} from '../../orchestration/entryMutations.js';
21	import {sendJson, sendUpsert, sendDelta, sendCommit, sendSkip, sendError, sendStreamEnd} from './sender.js';
22	import {log} from '../../shared/logger.js';
23	
24	interface StreamState {
25	  thinkingIndex: number | null;
26	  assistantIndex: number | null;
27	  suppressOutput: boolean;
28	  sentAssistantIndices: number[];
29	}
30	
31	type StateIndexKey = 'thinkingIndex' | 'assistantIndex';
32	type EntryFactory = typeof createThinkingEntry | typeof createAssistantEntry;
33	export function createMessageHandler(orchestrator: ChatOrchestrator, sessionStore?: SessionStore) {
34	  // Keyed by session, not socket: a resumed session can be open on more than one (specs/hal-engine-architecture/spec.md).
35	  const lock = new PerSessionLock();
36	  return function handleMessage(
37	    ws: WebSocket,
38	    session: ChatSession,
39	    rawMessage: unknown,
40	    signal?: AbortSignal
41	  ): Promise<void> {
42	    const validation = validateMessage(rawMessage);
43	    // Queued with no await before it, so a session's user_messages, a failed one too, are answered in arrival order.
44	    if (isUserMessageFrame(rawMessage)) {
45	      return lock.run(session.sessionId, () => answerInTurn(ws, session, orchestrator, validation, signal));
46	    }
47	    // An async action runs up to its first await at once, so a ping is answered now and a throw stays a rejection.
48	    return wsErrorHandler(ws, async () => answerFrame(ws, session, validation, sessionStore));
49	  };
50	}
51	
52	// The whole answer, an error and the stream_end included, goes out inside the lock: an error frame names no message.
53	async function answerInTurn(
54	  ws: WebSocket,
55	  session: ChatSession,
56	  orchestrator: ChatOrchestrator,
57	  validation: ValidationResult,
58	  signal: AbortSignal | undefined
59	): Promise<void> {
60	  // Its socket closed while it waited: nobody is left to read the answer, and a session's last close took its credentials.
61	  if (signal?.aborted || ws.readyState === WebSocket.CLOSING || ws.readyState === WebSocket.CLOSED) {
62	    log.info('message', 'queued message dropped: its socket closed', {sessionId: session.sessionId});
63	    return;
64	  }
65	  const startedAt = Date.now();
66	  try {
67	    await wsErrorHandler(ws, () => answerUserMessage(ws, session, orchestrator, validation, signal));
68	  } finally {
69	    endTurn(ws, session, signal, startedAt);
70	  }
71	}
72	
73	// A turn whose socket closed is abandoned rather than ended: nobody is left to read a terminal frame.
74	function endTurn(ws: WebSocket, session: ChatSession, signal: AbortSignal | undefined, startedAt: number): void {
75	  if (signal?.aborted) {
76	    log.info('message', 'turn abandoned: its socket closed', {
77	      sessionId: session.sessionId,
78	      elapsedMs: Date.now() - startedAt,
79	    });
80	    return;
81	  }
82	  sendStreamEnd(ws);
83	}
84	
85	async function answerUserMessage(
86	  ws: WebSocket,
87	  session: ChatSession,
88	  orchestrator: ChatOrchestrator,
89	  validation: ValidationResult,
90	  signal: AbortSignal | undefined
91	): Promise<void> {
92	  const message = validation.valid ? validation.data : undefined;
93	  if (message?.type === 'user_message') return handleUserMessage(ws, session, orchestrator, message.content, signal);
94	  answerFrame(ws, session, validation);
95	}
96	
97	// Answered off the per-session lock, beside ping: a history request is not a turn and mutates nothing.
98	async function answerFrame(
99	  ws: WebSocket,
100	  session: ChatSession,
101	  validation: ValidationResult,
102	  sessionStore?: SessionStore
103	): Promise<void> {
104	  if (!validation.valid) {
105	    log.warn('message', 'validation failed', {error: validation.error});
106	    sendError(ws, ErrorCodes.INVALID_MESSAGE, validation.error);
107	    return;
108	  }
109	
110	  const message = validation.data;
111	  if (message.type === 'ping') handlePing(ws, message.timestamp);
112	  if (message.type === 'list_sessions') await handleListSessions(ws, session, message, sessionStore);
113	}
114	
115	// The user id is read from the connection, never from the frame, so a client-named one cannot widen the answer.
116	async function handleListSessions(
117	  ws: WebSocket,
118	  session: ChatSession,
119	  message: ListSessionsMessage,
120	  sessionStore: SessionStore | undefined
121	): Promise<void> {
122	  try {
123	    const summaries = await sessionStore?.listFor?.(session.userId, {limit: message.limit, before: message.before});
124	    sendJson(ws, {type: 'session_list', sessions: (summaries ?? []).map(toSummaryFrame)});
125	  } catch (error) {
126	    const detail = error instanceof Error ? error.message : 'Unknown error';
127	    log.error('ws', 'listing conversations failed', {
128	      sessionId: session.sessionId,
129	      userId: session.userId,
130	      error: detail,
131	    });
132	    // The frame carries no store detail: what a client shows for a failed history is a failure, not an empty list.
133	    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to list conversations');
134	  }
135	}
136	
137	const toSummaryFrame = ({sessionId, createdAt, updatedAt, entryCount}: SessionSummary): SessionSummaryFrame => ({
138	  sessionId,
139	  createdAt: createdAt.toISOString(),
140	  updatedAt: updatedAt.toISOString(),
141	  entryCount,
142	});
143	
144	// Read from the raw frame, so a user_message that fails validation still gets its stream_end.
145	function isUserMessageFrame(rawMessage: unknown): boolean {
146	  return typeof rawMessage === 'object' && rawMessage !== null && Reflect.get(rawMessage, 'type') === 'user_message';
147	}
148	
149	async function wsErrorHandler(ws: WebSocket, action: () => Promise<void>): Promise<void> {
150	  try {
151	    await action();
152	  } catch (error) {
153	    const message = error instanceof Error ? error.message : 'Unknown error';
154	    const code = error instanceof AIError ? error.code : 'UNKNOWN';
155	    log.error('message', 'handling error', {error: message, code});
156	    if (error instanceof AIError && error.code === 'RATE_LIMITED') {
157	      sendError(ws, ErrorCodes.RATE_LIMITED, 'AI service is busy, please try again');
158	      return;
159	    }
160	    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to process message');
161	  }
162	}
163	
164	async function handleUserMessage(
165	  ws: WebSocket,
166	  session: ChatSession,
167	  orchestrator: ChatOrchestrator,
168	  content: string,
169	  signal: AbortSignal | undefined
170	): Promise<void> {
171	  log.info('message', 'user message received', {sessionId: session.sessionId, contentLength: content.length});
172	
173	  const userEntry = createUserEntry(content);
174	  const userIndex = appendEntry(session, userEntry);
175	  sendUpsert(ws, userIndex, userEntry);
176	
177	  const parser = new ThinkingTagParser();
178	  const state: StreamState = {
179	    thinkingIndex: null,
180	    assistantIndex: null,
181	    suppressOutput: false,
182	    sentAssistantIndices: [],
183	  };
184	
185	  let textChunkCount = 0;
186	
187	  try {
188	    for await (const chunk of orchestrator.processMessageStream(session, {signal})) {
189	      // Its socket closed: breaking returns the run's generator, so the run stops and its own teardown still runs.
190	      if (signal?.aborted) break;
191	      textChunkCount = logChunk(chunk, textChunkCount);
192	      processChunk(ws, session, state, parser, chunk);
193	    }
194	  } finally {
195	    // Anything still open here was cut short: a stop has already flushed the parser and committed every entry it opened.
196	    flushHeldText(ws, session, state, parser);
197	    closeCutOff(ws, session, state, 'thinkingIndex');
198	    closeCutOff(ws, session, state, 'assistantIndex');
199	  }
200	
201	  if (textChunkCount > 0) {
202	    log.debug('stream', `received ${textChunkCount} text chunks`);
203	  }
204	  log.info('stream', 'stream completed', {suppressed: state.suppressOutput, entries: session.entries.length});
205	}
206	
207	// Diagnostics only: counts a run of text chunks so it is logged once, not per token.
208	function logChunk(chunk: MessageChunk, textChunkCount: number): number {
209	  if (chunk.type === 'text') return textChunkCount + 1;
210	
211	  if (textChunkCount > 0) {
212	    log.debug('stream', `received ${textChunkCount} text chunks`);
213	  }
214	
215	  if (chunk.type === 'tool_result') {
216	    log.debug('stream', 'tool_result chunk', {
217	      messageCount: chunk.clientMessages.length,
218	      types: chunk.clientMessages.map(m => m.type),
219	    });
220	    return 0;
221	  }
222	
223	  log.debug('stream', 'chunk', {type: chunk.type});
224	  return 0;
225	}
226	
227	function processChunk(
228	  ws: WebSocket,
229	  session: ChatSession,
230	  state: StreamState,
231	  parser: ThinkingTagParser,
232	  chunk: MessageChunk
233	): void {
234	  if (chunk.type === 'text') return processTextChunk(ws, session, state, parser, chunk.text);
235	  if (chunk.type === 'tool_use') return processToolUseChunk(ws, session, chunk.toolCall);
236	  if (chunk.type === 'tool_result') return processToolResultChunk(ws, chunk.clientMessages);
237	  if (chunk.type === 'suppress_output') return processSuppressChunk(ws, session, state);
238	  if (chunk.type === 'stop') return processStopChunk(ws, session, state, parser);
239	}
240	
241	function processTextChunk(
242	  ws: WebSocket,
243	  session: ChatSession,
244	  state: StreamState,
245	  parser: ThinkingTagParser,
246	  text: string
247	): void {
248	  const segments = parser.push(text);
249	  for (const segment of segments) {
250	    handleTextSegment(ws, session, state, segment);
251	  }
252	}
